// server/_shared/country-token.ts
function normalizeCountryToken(value) {
  return String(value || "").normalize("NFKD").replace(new RegExp("\\p{Diacritic}", "gu"), "").toLowerCase().replace(/&/g, " and ").replace(/[''.(),/-]/g, " ").replace(/\s+/g, " ").trim();
}

